// Permanently updated with the authentic uploaded official seal

export const DEFAULT_OFFICIAL_SEAL_URL = "/uploads/jjf_media_1791272687577_76347e15.jpg";
export const BACKUP_OFFICIAL_SEAL_URL = "/uploads/jjf_media_1791272687577_76347e15.jpg";
export const OFFICIAL_SEAL_PNG_URL = "/official-seal.png";
export const OFFICIAL_SEAL_JPG_URL = "/official-seal.jpg";

/**
 * Embedded Base64 Data URL for the authentic uploaded official seal.
 * Guarantees instant, zero-delay, 100% offline-capable, and CORS-free rendering
 * in HTML5 Canvas, html2canvas, html-to-image, and PDF exports.
 * Never changes or reverts to any old seal upon downloading.
 */
export const OFFICIAL_SEAL_BASE64_DATA_URL = "data:image/jpeg;base64,";

/**
 * Returns the active official seal URL, prioritizing embedded base64 or authentic uploaded seal
 */
export function getActiveOfficialSealUrl(customUrl?: string): string {
  if (customUrl && customUrl.trim() && !customUrl.includes('old')) {
    return customUrl.trim();
  }
  if (typeof window !== 'undefined') {
    try {
      const stored = localStorage.getItem('jjf_custom_certificate_seal');
      if (stored && stored.trim() && !stored.includes('old')) {
        return stored.trim();
      }
    } catch {}
  }
  return OFFICIAL_SEAL_BASE64_DATA_URL;
}
